      .sort((a, b) => b.createdAt.localeCompare(a.createdAt) || a.agentContextId.localeCompare(b.agentContextId));
    return { items: items.slice(offset, offset + limit), nextOffset: offset + limit < items.length ? offset + limit : null };
  }
}


